// Package sauna prices bookings of the community sauna.
package sauna

import "fmt"

const (
	blockMinutes = 15
	maxMinutes   = 180
	blockCents   = 300
	guestCents   = 100
	towelCents   = 120
	minCents     = 300
)

// Booking is a request for the sauna cabin.
type Booking struct {
	Minutes   int
	StartHour int
	Members   int
	Guests    int
	Towels    bool
}

// Receipt is the price of a booking plus the lines that explain it.
type Receipt struct {
	Cents int
	Lines []string
}

// Charge prices a booking and lists how the price came about.
func Charge(b Booking) (Receipt, error) {
	// validation
	if b.Minutes <= 0 || b.Minutes%blockMinutes != 0 || b.Minutes > maxMinutes {
		return Receipt{}, fmt.Errorf("a session is 15..%d minutes in steps of 15, got %d", maxMinutes, b.Minutes)
	}
	if b.Members < 1 || b.Guests < 0 {
		return Receipt{}, fmt.Errorf("a booking needs at least one member and no negative guests")
	}
	if b.StartHour < 6 || b.StartHour > 22 {
		return Receipt{}, fmt.Errorf("the sauna is open 06:00-23:00, not at %d", b.StartHour)
	}

	// base rate
	blocks := b.Minutes / blockMinutes
	total := blocks * blockCents
	lines := []string{fmt.Sprintf("%d blocks x %d", blocks, blockCents)}

	// off-peak discount
	if b.StartHour < 17 {
		cut := total * 10 / 100
		total -= cut
		lines = append(lines, fmt.Sprintf("off-peak: -%d", cut))
	}

	// group discount
	if b.Members >= 4 {
		cut := total * 10 / 100
		total -= cut
		lines = append(lines, fmt.Sprintf("group: -%d", cut))
	}

	// minimum charge
	if total < minCents {
		lines = append(lines, "minimum charge applied")
		total = minCents
	}

	return Receipt{Cents: total, Lines: lines}, nil
}

