// Package post prices parcels for the mail counter.
package post

import "fmt"

const (
	// MaxWeightG is the heaviest parcel the desk accepts.
	MaxWeightG = 5000
	baseCents  = 350
	stepG      = 250
	stepCents  = 40
	zoneCents  = 190
	sigCents   = 150
	freeCover  = 20000
	capCents   = 6000
)

// Parcel is what the customer hands over at the counter.
type Parcel struct {
	WeightG       int
	Zone          int
	Signature     bool
	Fragile       bool
	DeclaredCents int
}

// Quote is a price together with one explanation line per charge.
type Quote struct {
	Cents int
	Notes []string
}

// check rejects parcels the desk cannot carry.
func check(p Parcel) error {
	if p.WeightG <= 0 || p.WeightG > MaxWeightG {
		return fmt.Errorf("weight %d g is outside 1..%d", p.WeightG, MaxWeightG)
	}
	if p.Zone < 1 || p.Zone > 4 {
		return fmt.Errorf("unknown zone %d", p.Zone)
	}
	return nil
}

// baseFare prices the weight alone.
func baseFare(p Parcel) (int, []string) {
	total := baseCents + ((p.WeightG-1)/stepG)*stepCents
	notes := []string{fmt.Sprintf("base for %d g: %d", p.WeightG, total)}
	return total, notes
}

// zoneSurcharge adds a fee for every zone beyond the first.
func zoneSurcharge(p Parcel, total int, notes []string) (int, []string) {
	if p.Zone > 1 {
		extra := (p.Zone - 1) * zoneCents
		total += extra
		notes = append(notes, fmt.Sprintf("zone %d: +%d", p.Zone, extra))
	}
	return total, notes
}

// signatureFee charges for proof of delivery.
func signatureFee(p Parcel, total int, notes []string) (int, []string) {
	if p.Signature {
		total += sigCents
		notes = append(notes, fmt.Sprintf("signature: +%d", sigCents))
	}
	return total, notes
}

// fragileHandling adds a percentage for careful handling.
func fragileHandling(p Parcel, total int, notes []string) (int, []string) {
	if p.Fragile {
		uplift := total * 25 / 100
		total += uplift
		notes = append(notes, fmt.Sprintf("fragile: +%d", uplift))
	}
	return total, notes
}

// insurance covers declared values above the free cover.
func insurance(p Parcel, total int, notes []string) (int, []string) {
	if p.DeclaredCents > freeCover {
		fee := (p.DeclaredCents - freeCover + 9999) / 10000 * 25
		total += fee
		notes = append(notes, fmt.Sprintf("insurance: +%d", fee))
	}
	return total, notes
}

// applyCap limits the price of heavy, expensive parcels.
func applyCap(total int, notes []string) (int, []string) {
	if total > capCents {
		total = capCents
		notes = append(notes, "capped")
	}
	return total, notes
}

// Price quotes a parcel, explaining every charge.
func Price(p Parcel) (Quote, error) {
	if err := check(p); err != nil {
		return Quote{}, err
	}
	total, notes := baseFare(p)
	total, notes = zoneSurcharge(p, total, notes)
	total, notes = signatureFee(p, total, notes)
	total, notes = fragileHandling(p, total, notes)
	total, notes = insurance(p, total, notes)
	total, notes = applyCap(total, notes)
	return Quote{Cents: total, Notes: notes}, nil
}

