func TestExRecorded(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantExJSON), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d outcomes, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("case %d: got %v, want %v", i, got[i], w)
		}
	}
}

