import clike as C

FILES = C.files([".go"], dirs=["seeds"])
LIMIT = 20
problems = []
fns = C.all_functions(FILES, "go")
if "Bill" not in [f.name for f in fns]:
    problems.append("the exported entry point Bill is missing")
for f in fns:
    if f.loc > LIMIT:
        problems.append("%s:%s has %d lines (limit %d)" % (f.file, f.name, f.loc, LIMIT))
if len(fns) < 5:
    problems.append("expected the logic to be spread over at least 5 functions, found %d" % len(fns))
C.report(problems)

