package post_test

import (
	"encoding/json"
	"reflect"
	"testing"

	"example.com/parcelpost/post"
)

const casesExJSON = `[{"WeightG": 501, "Zone": 3, "Signature": true, "Fragile": true, "DeclaredCents": 45000}, {"WeightG": 501, "Zone": 4, "Signature": true, "Fragile": false, "DeclaredCents": 0}, {"WeightG": 120, "Zone": 1, "Signature": true, "Fragile": false, "DeclaredCents": 45000}, {"WeightG": 30000, "Zone": 4, "Signature": false, "Fragile": true, "DeclaredCents": 2000}]`

type outcomeEx struct {
	Value *post.Quote `json:"value,omitempty"`
	Err   string `json:"err,omitempty"`
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var cases []post.Parcel
	if err := json.Unmarshal([]byte(casesExJSON), &cases); err != nil {
		panic(err)
	}
	var out []any
	for _, c := range cases {
		res, err := post.Price(c)
		var o outcomeEx
		if err != nil {
			o.Err = err.Error()
		} else {
			o.Value = &res
		}
		b, _ := json.Marshal(o)
		var v any
		_ = json.Unmarshal(b, &v)
		out = append(out, normEx(v))
	}
	return out
}

const wantExJSON = `[{"value": {"Cents": 1277, "Notes": ["base for 501 g: 680", "zone 3: +240", "signature: +150", "fragile: +107", "insurance: +100"]}}, {"value": {"Cents": 1190, "Notes": ["base for 501 g: 680", "zone 4: +360", "signature: +150"]}}, {"value": {"Cents": 930, "Notes": ["base for 120 g: 680", "signature: +150", "insurance: +100"]}}, {"err": "weight 30000 g is outside 1..5000"}]`

func TestExRecorded(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantExJSON), &want); err != nil {
		t.Fatal(err)
	}
	got := outcomesEx()
	if len(got) != len(want) {
		t.Fatalf("got %d outcomes, want %d", len(got), len(want))
	}
	for i := range want {
		w := normEx(want[i])
		if !reflect.DeepEqual(got[i], w) {
			t.Errorf("case %d: got %v, want %v", i, got[i], w)
		}
	}
}

