// Package seeds prices orders for the seed catalogue shop.
package seeds

import (
	"errors"
	"fmt"
)

const (
	bulkFrom      = 8000
	bulkPercent   = 8
	freeShipFrom  = 5000
	giftWrapCents = 400
)

var shipping = map[string]int{
	"FR": 1025,
	"PL": 350,
	"NL": 350,
	"SE": 325,
}

// Line is one product in an order.
type Line struct {
	SKU       string
	Qty       int
	UnitCents int
}

// Order is a basket going to one country.
type Order struct {
	Lines   []Line
	Country string
	Gift    bool
}

// Invoice is the amount due and the lines that explain it.
type Invoice struct {
	Cents int
	Lines []string
}

// check rejects empty orders, bad lines and unknown countries.
func check(o Order) error {
	if len(o.Lines) == 0 {
		return errors.New("an order needs at least one line")
	}
	for _, l := range o.Lines {
		if l.Qty <= 0 || l.UnitCents < 0 {
			return fmt.Errorf("bad line for %s", l.SKU)
		}
	}
	if _, ok := shipping[o.Country]; !ok {
		return fmt.Errorf("we do not ship to %q", o.Country)
	}
	return nil
}

// subtotal adds up the lines.
func subtotal(o Order) (int, []string) {
	total := 0
	var lines []string
	for _, l := range o.Lines {
		amount := l.Qty * l.UnitCents
		total += amount
		lines = append(lines, fmt.Sprintf("%s x%d: %d", l.SKU, l.Qty, amount))
	}
	return total, lines
}

// bulkDiscount takes a percentage off large baskets.
func bulkDiscount(total int, lines []string) (int, []string) {
	if total >= bulkFrom {
		cut := total * bulkPercent / 100
		total -= cut
		lines = append(lines, fmt.Sprintf("bulk discount: -%d", cut))
	}
	return total, lines
}

// shippingFee adds postage unless the basket qualifies for free shipping.
func shippingFee(o Order, total int, lines []string) (int, []string) {
	if total >= freeShipFrom {
		lines = append(lines, "free shipping")
	} else {
		fee := shipping[o.Country]
		total += fee
		lines = append(lines, fmt.Sprintf("shipping to %s: +%d", o.Country, fee))
	}
	return total, lines
}

// giftWrap adds a flat fee.
func giftWrap(o Order, total int, lines []string) (int, []string) {
	if o.Gift {
		total += giftWrapCents
		lines = append(lines, fmt.Sprintf("gift wrap: +%d", giftWrapCents))
	}
	return total, lines
}

// roundUp rounds the amount due up to the next 5 cents.
func roundUp(total int, lines []string) (int, []string) {
	if r := total % 5; r != 0 {
		lines = append(lines, fmt.Sprintf("rounded up by %d", 5-r))
		total += 5 - r
	}
	return total, lines
}

// Bill prices an order and itemises the invoice.
func Bill(o Order) (Invoice, error) {
	if err := check(o); err != nil {
		return Invoice{}, err
	}
	total, lines := subtotal(o)
	total, lines = bulkDiscount(total, lines)
	total, lines = shippingFee(o, total, lines)
	total, lines = giftWrap(o, total, lines)
	total, lines = roundUp(total, lines)
	return Invoice{Cents: total, Lines: lines}, nil
}

