const casesExJSON = `[{"Lines": [{"SKU": "basil-genovese", "Qty": 2, "UnitCents": 199}], "Country": "FR", "Gift": false}, {"Lines": [{"SKU": "radish-icicle", "Qty": 24, "UnitCents": 425}, {"SKU": "leek-bleu", "Qty": 2, "UnitCents": 899}, {"SKU": "tomato-heirloom", "Qty": 5, "UnitCents": 425}], "Country": "IT", "Gift": true}, {"Lines": [{"SKU": "basil-genovese", "Qty": 24, "UnitCents": 349}], "Country": "IT", "Gift": false}, {"Lines": [], "Country": "FR", "Gift": true}]`

type outcomeEx struct {
	Value *seeds.Invoice `json:"value,omitempty"`
	Err   string `json:"err,omitempty"`
}

func normEx(v any) any {
	switch x := v.(type) {
	case []any:
		if len(x) == 0 {
			return nil
		}
		for i := range x {
			x[i] = normEx(x[i])
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normEx(x[k])
		}
		return x
	}
	return v
}

func outcomesEx() []any {
	var cases []seeds.Order
	if err := json.Unmarshal([]byte(casesExJSON), &cases); err != nil {
		panic(err)
	}
	var out []any
	for _, c := range cases {
		res, err := seeds.Bill(c)
		var o outcomeEx
		if err != nil {
			o.Err = err.Error()
		} else {
			o.Value = &res
		}
		b, _ := json.Marshal(o)
		var v any
		_ = json.Unmarshal(b, &v)
		out = append(out, normEx(v))
	}
	return out
}

const wantExJSON = `[{"value": {"Cents": 1075, "Lines": ["basil-genovese x2: 398", "shipping to FR: +675", "rounded up by 2"]}}, {"value": {"Cents": 12965, "Lines": ["radish-icicle x24: 10200", "leek-bleu x2: 1798", "tomato-heirloom x5: 2125", "bulk discount: -1412", "free shipping", "gift wrap: +250", "rounded up by 4"]}}, {"value": {"Cents": 8315, "Lines": ["basil-genovese x24: 8376", "bulk discount: -837", "shipping to IT: +775", "rounded up by 1"]}}, {"err": "an order needs at least one line"}]`

func TestExRecorded(t *testing.T) {
	var want []any
	if err := json.Unmarshal([]byte(wantExJSON), &want); err != nil {
		t.Fatal(err)
	}
