// Package sauna prices bookings of the community sauna.
package sauna

import "fmt"

const (
	blockMinutes = 15
	maxMinutes   = 120
	blockCents   = 300
	guestCents   = 100
	towelCents   = 80
	minCents     = 500
)

// Booking is a request for the sauna cabin.
type Booking struct {
	Minutes   int
	StartHour int
	Members   int
	Guests    int
	Towels    bool
}

// Receipt is the price of a booking plus the lines that explain it.
type Receipt struct {
	Cents int
	Lines []string
}

// check validates the length, party and opening hours of a booking.
func check(b Booking) error {
	if b.Minutes <= 0 || b.Minutes%blockMinutes != 0 || b.Minutes > maxMinutes {
		return fmt.Errorf("a session is 15..%d minutes in steps of 15, got %d", maxMinutes, b.Minutes)
	}
	if b.Members < 1 || b.Guests < 0 {
		return fmt.Errorf("a booking needs at least one member and no negative guests")
	}
	if b.StartHour < 6 || b.StartHour > 22 {
		return fmt.Errorf("the sauna is open 06:00-23:00, not at %d", b.StartHour)
	}
	return nil
}

// baseRate charges per started block of 15 minutes.
func baseRate(b Booking) (int, []string) {
	blocks := b.Minutes / blockMinutes
	total := blocks * blockCents
	lines := []string{fmt.Sprintf("%d blocks x %d", blocks, blockCents)}
	return total, lines
}

// groupDiscount rewards parties of several members.
func groupDiscount(b Booking, total int, lines []string) (int, []string) {
	if b.Members >= 5 {
		cut := total * 12 / 100
		total -= cut
		lines = append(lines, fmt.Sprintf("group: -%d", cut))
	}
	return total, lines
}

// guestFees charges non-members per block.
func guestFees(b Booking, total int, lines []string) (int, []string) {
	if b.Guests > 0 {
		fee := b.Guests * guestCents * (b.Minutes / blockMinutes)
		total += fee
		lines = append(lines, fmt.Sprintf("%d guests: +%d", b.Guests, fee))
	}
	return total, lines
}

// towelHire adds a fee per person.
func towelHire(b Booking, total int, lines []string) (int, []string) {
	if b.Towels {
		n := b.Members + b.Guests
		total += n * towelCents
		lines = append(lines, fmt.Sprintf("towels x%d: +%d", n, n*towelCents))
	}
	return total, lines
}

// minimumCharge lifts tiny bookings to the minimum.
func minimumCharge(total int, lines []string) (int, []string) {
	if total < minCents {
		lines = append(lines, "minimum charge applied")
		total = minCents
	}
	return total, lines
}

// Charge prices a booking and lists how the price came about.
func Charge(b Booking) (Receipt, error) {
	if err := check(b); err != nil {
		return Receipt{}, err
	}
	total, lines := baseRate(b)
	total, lines = groupDiscount(b, total, lines)
	total, lines = guestFees(b, total, lines)
	total, lines = towelHire(b, total, lines)
	total, lines = minimumCharge(total, lines)
	return Receipt{Cents: total, Lines: lines}, nil
}

